run:
set -euo pipefail
[ "$(git rev-parse --abbrev-ref HEAD)" = {{branch}} ] || { echo "on $(git rev-parse --abbrev-ref HEAD), not the run's branch, so nothing was abandoned"; exit 0; }
kept=""
if [ -n "$(git status --porcelain -- . ':!.swarm')" ]; then
  git stash push -q -u -m {{branch}} -- . ':!.swarm'
  kept="; its uncommitted work is in git stash"
fi
git switch -q {{back_to}}
git branch -q -D {{branch}}
echo "deleted "{{branch}}"$kept"
